/// <summary>
/// Extension of the method modified
/// </summary>
public void modified()
{
    next modified();

    FormDataSource ledgerAllocationRuleDS = element.dataSource(formDataSourceStr(LedgerAllocationRule, LedgerAllocationRule));
    LedgerAllocationRule locLedgerAllocationRule = ledgerAllocationRuleDS.cursor();
    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVAAutomaticHeadcountUpdate)).enabled(locLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::FixedWeight);
    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVADestinationMainAccount)).enabled(locLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::FixedWeight);
    //                                                                                                            && locLedgerAllocationRule.AVAAutomaticHeadcountUpdate);
    //ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVADestinationMainAccount)).mandatory(locLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::FixedWeight);
    //                                                                                                    && locLedgerAllocationRule.AVAAutomaticHeadcountUpdate);
    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVADestinationMainAccount)).mandatory(false);
    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVAFPLDestinationMainAccount)).mandatory(false);

    if (locLedgerAllocationRule.AllocationMethod != LedgerAllocationMethod::FixedWeight)
    {
        //locLedgerAllocationRule.AVAAutomaticHeadcountUpdate = AVAAutomaticHeadcountUpdateEnum::None;
        locLedgerAllocationRule.AVADestinationMainAccount = strMin();
    } 

    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVADestinationAccountNum)).enabled(locLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);
    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVADestinationToLedgerDim)).enabled(locLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);
    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVADestinationDimAttributeName)).enabled(locLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);
    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVADestinationFromDimensionValue)).enabled(locLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);
    ledgerAllocationRuleDS.object(fieldNum(LedgerAllocationRule, AVADestinationToDimensionValue)).enabled(locLedgerAllocationRule.AllocationMethod == LedgerAllocationMethod::Basis);

    if (locLedgerAllocationRule.AllocationMethod != LedgerAllocationMethod::Basis)
    {
        locLedgerAllocationRule.AVADestinationAccountNum = strMin();
        locLedgerAllocationRule.AVADestinationToLedgerDim = 0;
        locLedgerAllocationRule.AVADestinationDimAttributeName = strMin();
        locLedgerAllocationRule.AVADestinationFromDimensionValue = strMin();
        locLedgerAllocationRule.AVADestinationToDimensionValue = strMin();
    }
}
